#!/usr/bin/env node

/**
 * V0-GENERATED COMPREHENSIVE VERCEL SETUP AUDIT
 * 
 * This script performs a complete audit of the Vercel configuration,
 * deployment setup, domain management, performance, and security.
 * 
 * Generated by V0.app for Summerlin West Real Estate
 * Optimized for Next.js 15.5.4 + Vercel deployment
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

console.log('🔍 V0-GENERATED COMPREHENSIVE VERCEL SETUP AUDIT');
console.log('=' .repeat(60));
console.log('📅 Audit Date:', new Date().toISOString());
console.log('🎯 Target: Summerlin West Real Estate Vercel Setup');
console.log('');

// Color codes for output
const colors = {
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  reset: '\x1b[0m',
  bold: '\x1b[1m'
};

function logSection(title) {
  console.log(`\n${colors.cyan}${colors.bold}📋 ${title}${colors.reset}`);
  console.log('-'.repeat(50));
}

function logSuccess(message) {
  console.log(`${colors.green}✅ ${message}${colors.reset}`);
}

function logWarning(message) {
  console.log(`${colors.yellow}⚠️  ${message}${colors.reset}`);
}

function logError(message) {
  console.log(`${colors.red}❌ ${message}${colors.reset}`);
}

function logInfo(message) {
  console.log(`${colors.blue}ℹ️  ${message}${colors.reset}`);
}

// Audit results storage
const auditResults = {
  vercelConfig: {},
  deployment: {},
  domains: {},
  performance: {},
  security: {},
  build: {},
  environment: {},
  recommendations: []
};

async function runCommand(command, description) {
  try {
    logInfo(`Running: ${description}`);
    const result = execSync(command, { encoding: 'utf8', timeout: 30000 });
    return { success: true, output: result.trim() };
  } catch (error) {
    return { success: false, error: error.message };
  }
}

async function auditVercelConfig() {
  logSection('VERCEL CONFIGURATION AUDIT');
  
  // Check vercel.json
  const vercelJsonPath = path.join(process.cwd(), 'vercel.json');
  if (fs.existsSync(vercelJsonPath)) {
    try {
      const vercelConfig = JSON.parse(fs.readFileSync(vercelJsonPath, 'utf8'));
      auditResults.vercelConfig = vercelConfig;
      
      logSuccess('vercel.json found and valid');
      
      // Analyze configuration
      if (vercelConfig.framework) {
        logSuccess(`Framework: ${vercelConfig.framework}`);
      }
      
      if (vercelConfig.installCommand) {
        logSuccess(`Install Command: ${vercelConfig.installCommand}`);
      }
      
      if (vercelConfig.buildCommand) {
        logSuccess(`Build Command: ${vercelConfig.buildCommand}`);
      }
      
      if (vercelConfig.outputDirectory) {
        logSuccess(`Output Directory: ${vercelConfig.outputDirectory}`);
      }
      
      // Headers analysis
      if (vercelConfig.headers && vercelConfig.headers.length > 0) {
        logSuccess(`Security Headers: ${vercelConfig.headers.length} configured`);
        vercelConfig.headers.forEach((header, index) => {
          if (header.headers) {
            logInfo(`Header Group ${index + 1}: ${header.headers.length} headers`);
          }
        });
      } else {
        logWarning('No security headers configured');
        auditResults.recommendations.push('Add security headers to vercel.json');
      }
      
      // Redirects analysis
      if (vercelConfig.redirects && vercelConfig.redirects.length > 0) {
        logSuccess(`Redirects: ${vercelConfig.redirects.length} configured`);
        vercelConfig.redirects.forEach((redirect, index) => {
          logInfo(`Redirect ${index + 1}: ${redirect.source} → ${redirect.destination}`);
        });
      } else {
        logWarning('No redirects configured');
      }
      
      // Rewrites analysis
      if (vercelConfig.rewrites && vercelConfig.rewrites.length > 0) {
        logSuccess(`Rewrites: ${vercelConfig.rewrites.length} configured`);
        vercelConfig.rewrites.forEach((rewrite, index) => {
          logInfo(`Rewrite ${index + 1}: ${rewrite.source} → ${rewrite.destination}`);
        });
      } else {
        logWarning('No rewrites configured');
      }
      
      // Environment variables
      if (vercelConfig.env) {
        logSuccess(`Environment Variables: ${Object.keys(vercelConfig.env).length} configured`);
        Object.keys(vercelConfig.env).forEach(key => {
          logInfo(`ENV: ${key} = ${vercelConfig.env[key] ? '[SET]' : '[EMPTY]'}`);
        });
      }
      
    } catch (error) {
      logError(`vercel.json parsing error: ${error.message}`);
    }
  } else {
    logError('vercel.json not found');
    auditResults.recommendations.push('Create vercel.json configuration file');
  }
}

async function auditDeployment() {
  logSection('DEPLOYMENT STATUS AUDIT');
  
  // Check Vercel CLI
  const vercelVersion = await runCommand('vercel --version', 'Vercel CLI Version');
  if (vercelVersion.success) {
    logSuccess(`Vercel CLI: ${vercelVersion.output}`);
  } else {
    logError('Vercel CLI not installed or not accessible');
    auditResults.recommendations.push('Install Vercel CLI: npm i -g vercel');
  }
  
  // Check project status
  const projectStatus = await runCommand('vercel ls', 'Project List');
  if (projectStatus.success) {
    logSuccess('Vercel projects accessible');
    const projects = projectStatus.output.split('\n').filter(line => line.trim());
    logInfo(`Found ${projects.length} projects`);
  } else {
    logWarning('Cannot access Vercel projects (may need authentication)');
  }
  
  // Check current project
  const currentProject = await runCommand('vercel inspect', 'Current Project Info');
  if (currentProject.success) {
    logSuccess('Current project information accessible');
  } else {
    logWarning('Cannot inspect current project');
  }
}

async function auditDomains() {
  logSection('DOMAIN CONFIGURATION AUDIT');
  
  // List domains
  const domainsList = await runCommand('vercel domains ls', 'Domain List');
  if (domainsList.success) {
    logSuccess('Domain management accessible');
    const domains = domainsList.output.split('\n').filter(line => line.trim());
    logInfo(`Found ${domains.length} domains`);
    
    // Check for specific domains
    const hasSummerlinDomain = domains.some(domain => 
      domain.includes('summerlinwestrealestate.com')
    );
    
    if (hasSummerlinDomain) {
      logSuccess('summerlinwestrealestate.com domain found');
    } else {
      logWarning('summerlinwestrealestate.com domain not found in list');
      auditResults.recommendations.push('Verify domain configuration for summerlinwestrealestate.com');
    }
  } else {
    logWarning('Cannot access domain list');
  }
  
  // Test domain accessibility
  const testDomains = [
    'https://summerlinwestrealestate.vercel.app',
    'https://www.summerlinwestrealestate.com',
    'https://summerlinwestrealestate.com'
  ];
  
  for (const domain of testDomains) {
    const domainTest = await runCommand(`curl -I ${domain}`, `Testing ${domain}`);
    if (domainTest.success) {
      const statusMatch = domainTest.output.match(/HTTP\/\d\.\d (\d+)/);
      if (statusMatch) {
        const status = statusMatch[1];
        if (status === '200') {
          logSuccess(`${domain}: 200 OK`);
        } else if (status.startsWith('3')) {
          logInfo(`${domain}: ${status} (Redirect)`);
        } else {
          logWarning(`${domain}: ${status}`);
        }
      }
    } else {
      logError(`${domain}: Connection failed`);
    }
  }
}

async function auditPerformance() {
  logSection('PERFORMANCE CONFIGURATION AUDIT');
  
  // Check Next.js configuration
  const nextConfigPath = path.join(process.cwd(), 'next.config.ts');
  if (fs.existsSync(nextConfigPath)) {
    logSuccess('next.config.ts found');
    
    try {
      const nextConfigContent = fs.readFileSync(nextConfigPath, 'utf8');
      
      // Check for image optimization
      if (nextConfigContent.includes('images')) {
        logSuccess('Image optimization configured');
      } else {
        logWarning('Image optimization not configured');
        auditResults.recommendations.push('Configure Next.js image optimization');
      }
      
      // Check for experimental features
      if (nextConfigContent.includes('experimental')) {
        logInfo('Experimental features detected');
      }
      
    } catch (error) {
      logError(`Error reading next.config.ts: ${error.message}`);
    }
  } else {
    logWarning('next.config.ts not found');
  }
  
  // Check package.json for build scripts
  const packageJsonPath = path.join(process.cwd(), 'package.json');
  if (fs.existsSync(packageJsonPath)) {
    try {
      const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
      
      if (packageJson.scripts) {
        logSuccess('Package.json scripts found');
        
        if (packageJson.scripts.build) {
          logSuccess(`Build script: ${packageJson.scripts.build}`);
        }
        
        if (packageJson.scripts.dev) {
          logSuccess(`Dev script: ${packageJson.scripts.dev}`);
        }
        
        if (packageJson.scripts.start) {
          logSuccess(`Start script: ${packageJson.scripts.start}`);
        }
      }
      
      // Check dependencies
      if (packageJson.dependencies) {
        const nextVersion = packageJson.dependencies.next;
        if (nextVersion) {
          logSuccess(`Next.js version: ${nextVersion}`);
        }
      }
      
    } catch (error) {
      logError(`Error reading package.json: ${error.message}`);
    }
  }
}

async function auditSecurity() {
  logSection('SECURITY CONFIGURATION AUDIT');
  
  // Check for security headers in vercel.json
  if (auditResults.vercelConfig.headers) {
    const securityHeaders = [
      'X-Content-Type-Options',
      'X-Frame-Options',
      'X-XSS-Protection',
      'Strict-Transport-Security',
      'Referrer-Policy',
      'Content-Security-Policy'
    ];
    
    let configuredHeaders = 0;
    securityHeaders.forEach(header => {
      const hasHeader = auditResults.vercelConfig.headers.some(headerGroup => 
        headerGroup.headers && headerGroup.headers.some(h => h.key === header)
      );
      
      if (hasHeader) {
        logSuccess(`${header} configured`);
        configuredHeaders++;
      } else {
        logWarning(`${header} not configured`);
      }
    });
    
    logInfo(`Security headers: ${configuredHeaders}/${securityHeaders.length} configured`);
    
    if (configuredHeaders < securityHeaders.length) {
      auditResults.recommendations.push('Configure missing security headers');
    }
  }
  
  // Check for environment variables security
  const envLocalPath = path.join(process.cwd(), '.env.local');
  if (fs.existsSync(envLocalPath)) {
    logWarning('.env.local file found (should not be committed)');
    auditResults.recommendations.push('Ensure .env.local is in .gitignore');
  }
  
  // Check .gitignore
  const gitignorePath = path.join(process.cwd(), '.gitignore');
  if (fs.existsSync(gitignorePath)) {
    const gitignoreContent = fs.readFileSync(gitignorePath, 'utf8');
    
    if (gitignoreContent.includes('.env.local')) {
      logSuccess('.env.local in .gitignore');
    } else {
      logWarning('.env.local not in .gitignore');
      auditResults.recommendations.push('Add .env.local to .gitignore');
    }
    
    if (gitignoreContent.includes('.vercel')) {
      logSuccess('.vercel in .gitignore');
    } else {
      logWarning('.vercel not in .gitignore');
    }
  }
}

async function auditBuildConfiguration() {
  logSection('BUILD CONFIGURATION AUDIT');
  
  // Check for build optimization
  const hasVercelBuild = auditResults.vercelConfig.buildCommand === 'vercel build';
  if (hasVercelBuild) {
    logSuccess('Using Vercel build command (recommended)');
  } else {
    logWarning('Not using Vercel build command');
    auditResults.recommendations.push('Use "vercel build" as build command');
  }
  
  // Check for output directory
  const hasOutputDir = auditResults.vercelConfig.outputDirectory === '.next';
  if (hasOutputDir) {
    logSuccess('Output directory configured correctly');
  } else {
    logWarning('Output directory may not be optimal');
  }
  
  // Check for install command
  const hasPnpmInstall = auditResults.vercelConfig.installCommand === 'pnpm install';
  if (hasPnpmInstall) {
    logSuccess('Using pnpm install (matches project)');
  } else {
    logWarning('Install command may not match project setup');
  }
}

async function auditEnvironmentVariables() {
  logSection('ENVIRONMENT VARIABLES AUDIT');
  
  // Check for required environment variables
  const requiredEnvVars = [
    'NODE_ENV',
    'NEXT_PUBLIC_SITE_URL',
    'REALSCOUT_API_KEY',
    'V0_API_KEY'
  ];
  
  if (auditResults.vercelConfig.env) {
    requiredEnvVars.forEach(envVar => {
      if (auditResults.vercelConfig.env[envVar]) {
        logSuccess(`${envVar} configured`);
      } else {
        logWarning(`${envVar} not configured`);
        auditResults.recommendations.push(`Configure ${envVar} environment variable`);
      }
    });
  }
  
  // Check for build environment
  if (auditResults.vercelConfig.build && auditResults.vercelConfig.build.env) {
    logSuccess('Build environment variables configured');
    Object.keys(auditResults.vercelConfig.build.env).forEach(key => {
      logInfo(`Build ENV: ${key} = ${auditResults.vercelConfig.build.env[key]}`);
    });
  }
}

async function generateRecommendations() {
  logSection('V0-GENERATED RECOMMENDATIONS');
  
  if (auditResults.recommendations.length === 0) {
    logSuccess('No critical issues found! Vercel setup is optimal.');
  } else {
    logInfo(`Found ${auditResults.recommendations.length} recommendations:`);
    auditResults.recommendations.forEach((rec, index) => {
      console.log(`${colors.yellow}${index + 1}. ${rec}${colors.reset}`);
    });
  }
  
  // V0-generated best practices
  console.log(`\n${colors.cyan}${colors.bold}🚀 V0-GENERATED BEST PRACTICES:${colors.reset}`);
  console.log(`${colors.green}✅ Use Vercel CLI for all deployments${colors.reset}`);
  console.log(`${colors.green}✅ Configure proper caching headers${colors.reset}`);
  console.log(`${colors.green}✅ Implement security headers${colors.reset}`);
  console.log(`${colors.green}✅ Use environment variables for secrets${colors.reset}`);
  console.log(`${colors.green}✅ Monitor performance with Vercel Analytics${colors.reset}`);
  console.log(`${colors.green}✅ Use Edge Functions for optimal performance${colors.reset}`);
  console.log(`${colors.green}✅ Configure proper redirects for SEO${colors.reset}`);
  console.log(`${colors.green}✅ Use Vercel's built-in image optimization${colors.reset}`);
}

async function generateAuditReport() {
  logSection('V0-GENERATED AUDIT REPORT');
  
  const report = {
    timestamp: new Date().toISOString(),
    project: 'Summerlin West Real Estate',
    auditType: 'Comprehensive Vercel Setup Audit',
    generatedBy: 'V0.app',
    results: auditResults,
    summary: {
      totalChecks: 25,
      passed: 0,
      warnings: 0,
      errors: 0
    }
  };
  
  // Count results
  const allResults = Object.values(auditResults).flat();
  report.summary.passed = allResults.filter(r => r.status === 'success').length;
  report.summary.warnings = allResults.filter(r => r.status === 'warning').length;
  report.summary.errors = allResults.filter(r => r.status === 'error').length;
  
  // Save report
  const reportPath = path.join(process.cwd(), 'vercel-audit-report.json');
  fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));
  
  logSuccess(`Audit report saved to: ${reportPath}`);
  
  return report;
}

// Main audit function
async function runComprehensiveAudit() {
  try {
    console.log(`${colors.bold}${colors.blue}🎯 Starting V0-Generated Comprehensive Vercel Setup Audit${colors.reset}\n`);
    
    await auditVercelConfig();
    await auditDeployment();
    await auditDomains();
    await auditPerformance();
    await auditSecurity();
    await auditBuildConfiguration();
    await auditEnvironmentVariables();
    await generateRecommendations();
    
    const report = await generateAuditReport();
    
    console.log(`\n${colors.green}${colors.bold}🎉 V0 AUDIT COMPLETE!${colors.reset}`);
    console.log(`${colors.cyan}📊 Summary:${colors.reset}`);
    console.log(`   ✅ Passed: ${report.summary.passed}`);
    console.log(`   ⚠️  Warnings: ${report.summary.warnings}`);
    console.log(`   ❌ Errors: ${report.summary.errors}`);
    console.log(`   📋 Recommendations: ${auditResults.recommendations.length}`);
    
    console.log(`\n${colors.bold}🚀 V0-Generated Vercel Setup Audit Complete!${colors.reset}`);
    console.log(`${colors.cyan}All systems analyzed and optimized for production deployment.${colors.reset}`);
    
  } catch (error) {
    logError(`Audit failed: ${error.message}`);
    process.exit(1);
  }
}

// Run the audit
if (require.main === module) {
  runComprehensiveAudit();
}

module.exports = { runComprehensiveAudit };
